// Üretilen dosya: tool/ozgun/uret.py. Fizik · Manyetizma ve elektromanyetik indüksiyon (zor).
const ozPhysics12Zor = <(String, String, List<String>, String)>[
  ('Yarıçapı 10 cm olan yarım çember biçimindeki bir telden 4 A akım geçiyor. Çemberin merkezinde alan yaklaşık kaç tesladır? (μ₀ = 4π × 10⁻⁷ T·m/A, π = 3,14)', '1,26 × 10⁻⁵ T', ['2,5 × 10⁻⁵ T', '6,3 × 10⁻⁶ T', '1,26 × 10⁻⁴ T'], 'Yarım çemberde B = μ₀I/(4R) = 4π×10⁻⁷ · 4 / 0,4 ≈ 1,26 × 10⁻⁵ T.'),
  ('Bir telin 15 cm yarıçaplı bir çemberin dörtte birini oluşturan yay biçiminde bükülmüş kısmından 6 A akım akıyor. Yayın eğrilik merkezindeki alan yaklaşık kaç tesladır? (μ₀ = 4π × 10⁻⁷ T·m/A, π = 3,14)', '6,28 × 10⁻⁶ T', ['1,26 × 10⁻⁵ T', '3,14 × 10⁻⁶ T', '2,5 × 10⁻⁵ T'], 'Çeyrek çemberde B = μ₀I/(8R) = 4π×10⁻⁷ · 6 / 1,2 ≈ 6,28 × 10⁻⁶ T.'),
  ('Metresinde 1000 sarım bulunan uzun bir bobinden 2 A geçiyor. Bobine bağıl geçirgenliği 500 olan bir demir çekirdek yerleştirilirse iç alan yaklaşık kaç tesla olur? (μ₀ = 4π × 10⁻⁷ T·m/A)', '1,26 T', ['2,5 × 10⁻³ T', '0,63 T', '12,6 T'], 'B = μrμ₀nI = 500 · 4π×10⁻⁷ · 1000 · 2 ≈ 1,26 T.'),
  ('Proton ve alfa parçacığı (4 u kütleli, +2e yüklü) aynı düzgün manyetik alana dik girerek çembersel hareket yapıyor. Alfa parçacığının dolanma periyodu protonunkinin kaç katıdır?', '2', ['1/2', '4', '1'], 'T = 2πm/(qB) ∝ m/q; alfa için m/q oranı protonunkinin 4/2 = 2 katıdır.'),
  ('Aynı kinetik enerjiyle aynı düzgün alana dik giren bir proton ile bir elektronun yörünge yarıçapları oranı r(proton)/r(elektron) yaklaşık kaçtır? (m(proton)/m(elektron) ≈ 1836)', '43', ['1836', '1/43', '2'], 'r = √(2mK)/(qB) olduğundan oran √(m_p/m_e) = √1836 ≈ 43 bulunur.'),
  ('Hızı 2 × 10⁶ m/s olan bir elektron, 1 mT\'lık düzgün manyetik alana alanla 60° açı yapacak biçimde giriyor. Helisel yörüngenin adımı (bir turda alan doğrultusunda alınan yol) yaklaşık kaç santimetredir? (T = 2πm/(eB) ≈ 3,58 × 10⁻⁸ s)', '3,6 cm', ['6,25 cm', '1,8 cm', '7,2 cm'], 'Alana paralel bileşen v cos60° = 10⁶ m/s\'dir; adım = 10⁶ · 3,58×10⁻⁸ ≈ 3,6×10⁻² m.'),
  ('Bir siklotronda 1 T\'lık alan ve 0,5 m çıkış yarıçapı kullanılıyor. Çıkan protonların kinetik enerjisi yaklaşık kaç MeV\'dir? (q = 1,6 × 10⁻¹⁹ C, m = 1,67 × 10⁻²⁷ kg)', '12 MeV', ['6 MeV', '24 MeV', '1,2 MeV'], 'K = (qBR)²/(2m) = (8×10⁻²⁰)²/(3,34×10⁻²⁷) ≈ 1,9×10⁻¹² J ≈ 12 MeV.'),
  ('Aynı gerilimle hızlandırılan, yükleri eşit iki iyonun kütle oranı 4 : 1\'dir. İyonlar aynı düzgün alana dik girdiğinde yarıçap oranı kaçtır?', '2 : 1', ['4 : 1', '16 : 1', '1 : 2'], 'qV = ½mv² ve r = mv/(qB) birleştirilince r ∝ √(m/q) bulunur; oran √4 = 2 olur.'),
  ('Bir öğrenci, 1 mA\'de tam sapan ve bobin direnci 50 Ω olan hassas bir ölçü aletine seri bir direnç ekleyerek 0–10 V aralığında çalışan bir voltmetre yapmak istiyor. Eklemesi gereken direnç kaç ohmdur?', '9950 Ω', ['10 000 Ω', '950 Ω', '10 050 Ω'], 'Toplam direnç V/Ig = 10/0,001 = 10 000 Ω olmalı; seri direnç 10 000 − 50 = 9950 Ω\'dur.'),
  ('12 V\'luk kaynağa bağlı, sargı direnci 2 Ω olan bir DC motor sabit hızla dönerken 8 V zıt emk üretiyor. Motorun mekanik güce çevirdiği güç kaç watt\'tır?', '16 W', ['8,5 W', '24 W', '32 W'], 'I = (12 − 8)/2 = 2 A; mekanik güç = zıt emk · akım = 8 · 2 = 16 W (sargıda I²R = 8 W ısıya gider).'),
  ('Kalınlığı 0,1 mm olan bakır bir şeritten 2 A akım geçerken şerit, yüzeyine dik 0,5 T\'lık alana konuyor. Bakırda serbest elektron yoğunluğu 8,5 × 10²⁸ m⁻³ ise Hall gerilimi yaklaşık kaçtır? (V = BI/(nqt), q = 1,6 × 10⁻¹⁹ C)', '0,74 μV', ['74 μV', '7,4 mV', '0,074 μV'], 'V = 0,5 · 2 / (8,5×10²⁸ · 1,6×10⁻¹⁹ · 10⁻⁴) ≈ 7,4 × 10⁻⁷ V ≈ 0,74 μV.'),
  ('Kenarı 20 cm olan kare bir çerçevenin düzlemi, 0,8 T\'lık düzgün alan çizgileriyle 30° açı yapıyor. Çerçeveden geçen akı kaç weberdir?', '1,6 × 10⁻² Wb', ['2,85 × 10⁻² Wb', '3,2 × 10⁻² Wb', '1,6 × 10⁻³ Wb'], 'Normal ile alan arasındaki açı 60°\'dir: Φ = 0,8 · 0,04 · cos60° = 1,6 × 10⁻² Wb. Açının düzlemle verildiğine dikkat edilmelidir.'),
  ('Tek sarımlı bir halkadan geçen akı Φ = 0,4t² − 2t (Wb, t saniye) bağıntısıyla değişiyor. Halkada indüklenen emk, t = 2,5 s anında kaç volttur?', '0', ['1 V', '2 V', '0,4 V'], 'ε = −dΦ/dt = −(0,8t − 2); t = 2,5 s için 0,8·2,5 − 2 = 0 olduğundan emk sıfırdır.'),
  ('10 sarımlı bir bobinden geçen akı Φ = 0,4t² − 2t (Wb, t saniye) bağıntısıyla değişiyor. t = 3 s anında emk\'nın büyüklüğü kaç volttur?', '4 V', ['0,4 V', '40 V', '14 V'], '|ε| = N|dΦ/dt| = 10 · |0,8·3 − 2| = 10 · 0,4 = 4 V.'),
  ('50 sarımlı ve toplam direnci 10 Ω olan bir bobinden geçen akı 0,03 Wb\'den sıfıra iniyor. Devreden geçen toplam yük kaç coulomb olur?', '0,15 C', ['0,03 C', '1,5 C', '0,015 C'], 'q = NΔΦ/R = 50 · 0,03 / 10 = 0,15 C; toplam yük akının değişim süresinden bağımsızdır.'),
  ('Yarıçapı r = 0,1 m olan esnek bir iletken halka, 0,5 T\'lık alana dik düzlemde yarıçapı 0,01 m/s hızla büyüyecek biçimde genişletiliyor. Halkada indüklenen emk yaklaşık kaç milivolttur? (π = 3,14)', '3,14 mV', ['6,28 mV', '0,314 mV', '31,4 mV'], 'ε = B dA/dt = B · 2πr · dr/dt = 0,5 · 2 · 3,14 · 0,1 · 0,01 ≈ 3,14 × 10⁻³ V.'),
  ('Düşey bir çerçevede, B = 1 T\'lık yatay alanda serbest kayan 0,05 kg kütleli ve 0,5 m uzunluklu bir çubuk, toplam direnci 0,5 Ω olan kapalı devreyle sürtünmesiz biçimde düşüyor. Ulaşacağı sınır hız kaç m/s\'dir? (g = 10 m/s²)', '1 m/s', ['0,5 m/s', '2 m/s', '10 m/s'], 'Sınır hızda mg = B²L²v/R; v = mgR/(B²L²) = 0,05·10·0,5/(1·0,25) = 1 m/s.'),
  ('Kenarı 0,2 m ve direnci 0,1 Ω olan kare bir çerçeve, 0,5 T\'lık düzgün alana 2 m/s hızla sabit olarak giriyor. Giriş sırasında çerçeveyi sabit hızda tutmak için gereken kuvvet kaç newtondur?', '0,2 N', ['0,1 N', '2 N', '0,02 N'], 'ε = 0,2 V; I = 2 A; F = BIa = 0,5 · 2 · 0,2 = 0,2 N.'),
  ('Bir iletken çubuk, 0,5 T\'lık düzgün alanda alanla 30° açı yapacak doğrultuda 10 m/s hızla hareket ettiriliyor. Çubuk boyu 0,6 m ve çubuk hem hıza hem alana diktir. Uçları arasındaki emk kaç volttur?', '1,5 V', ['3 V', '2,6 V', '0,75 V'], 'ε = BLv sinθ = 0,5 · 0,6 · 10 · sin30° = 1,5 V.'),
  ('Sürtünmesiz iki ray üzerindeki çubuk, 6 V emk\'lı bir pille sürülüyor. Raylar arası 0,4 m, alan 0,5 T\'dır. Çubuk hızlandıkça ters emk oluşur. Çubuğun ulaşacağı sınır hız kaç m/s\'dir?', '30 m/s', ['12 m/s', '60 m/s', '3,5 m/s'], 'Sınır hızda ters emk pil emk\'sına eşitlenir ve akım sıfırlanır: BLv = 6 → v = 6/(0,5 · 0,4) = 30 m/s.'),
  ('Uzunluğu 0,4 m olan bir iletken çubuk, bir ucu etrafında 0,2 T\'lık alana dik düzlemde 50 rad/s açısal hızla dönüyor. Çubuğun uçları arasındaki emk kaç volttur?', '0,8 V', ['1,65 V', '0,4 V', '3,2 V'], 'ε = ½ B ω L² = 0,5 · 0,2 · 50 · 0,16 = 0,8 V.'),
  ('Yarıçapı 10 cm olan bakır bir disk, 0,5 T\'lık alana dik olarak 60 rad/s açısal hızla dönüyor. Disk merkezi ile kenarı arasında oluşan emk kaç volttur?', '0,15 V', ['0,3 V', '1,5 V', '0,015 V'], 'ε = ½ B ω R² = 0,5 · 0,5 · 60 · 0,01 = 0,15 V.'),
  ('12 V\'luk bir pil, 6 Ω\'luk bir direnç ve 0,3 H\'lik bir bobin seri bağlanıyor. Anahtar kapatıldığı anda akımın artış hızı (dI/dt) kaç A/s\'dir?', '40 A/s', ['2 A/s', '4 A/s', '200 A/s'], 't = 0\'da ε = L·dI/dt olduğundan dI/dt = 12/0,3 = 40 A/s\'dir.'),
  ('1 T\'lık bir manyetik alanın boşluktaki enerji yoğunluğu yaklaşık kaç J/m³\'tür? (u = B²/(2μ₀), μ₀ = 4π × 10⁻⁷ T·m/A)', '4 × 10⁵ J/m³', ['8,5 × 10⁵ J/m³', '2 × 10⁵ J/m³', '4 × 10³ J/m³'], 'u = 1² / (2 · 4π×10⁻⁷) ≈ 3,98 × 10⁵ J/m³.'),
  ('Bir jeneratörün emk\'sı ε = ε₀ sin(ωt) ile veriliyor. ε₀ = 100 V ve f = 50 Hz ise t = 1/600 s anında anlık emk kaç volttur?', '50 V', ['100 V', '86,6 V', '25 V'], 'ωt = 2π·50/600 = π/6; ε = 100 · sin30° = 50 V.'),
  ('Faz-nötr arasında 220 V ölçülen üç fazlı bir şebekede iki faz arasındaki gerilim yaklaşık kaç volttur?', '380 V', ['440,5 V', '311 V', '660 V'], 'Faz-faz gerilimi, faz-nötr geriliminin √3 katıdır: 220 · 1,73 ≈ 380 V.'),
  ('Direnci 30 Ω, indüktif reaktansı 40 Ω olan seri RL devresine etkin değeri 100 V olan alternatif gerilim uygulanıyor. Devrede harcanan ortalama güç kaç watt\'tır?', '120 W', ['200,5 W', '160 W', '333 W'], 'Z = 50 Ω, I = 2 A; P = I²R = 4 · 30 = 120 W (yalnızca direnç güç harcar).'),
  ('Bir bobin ile bir direncin seri bağlandığı alternatif akım devresinde bobinin reaktansı direncin tam kendisine eşittir. Kaynak gerilimi ile devre akımı arasındaki faz farkı kaç derecedir?', '45°', ['30°', '60°', '90°'], 'tanφ = XL/R = 1 olduğundan φ = 45°; gerilim akımdan ileridedir.'),
  ('Seri RLC devresinde L = 0,1 H, C = 10 μF ve R = 10 Ω\'dur. Devrenin kalite faktörü (Q = ω₀L/R) kaçtır?', '10', ['100', '1', '0,1'], 'ω₀ = 1/√(LC) = 1000 rad/s; Q = 1000 · 0,1 / 10 = 10.'),
  ('L = 0,1 H, C = 10 μF, R = 10 Ω olan seri RLC devresine rezonans frekansında 20 V etkin gerilim uygulanıyor. Bobin uçlarındaki etkin gerilim kaç volttur?', '200 V', ['20 V', '2 V', '100 V'], 'Rezonansta I = V/R = 2 A; XL = ω₀L = 100 Ω olduğundan VL = 200 V; kaynağın on katıdır.'),
  ('20 MW\'lık elektrik gücü 200 kV\'luk bir hatla iletiliyor. Hattın toplam direnci 5 Ω ise hatta ısı olarak harcanan güç kaç kilowatt\'tır? (P = VI)', '50 kW', ['500 kW', '5 kW', '1000 kW'], 'I = P/V = 20×10⁶/2×10⁵ = 100 A; kayıp = I²R = 10⁴ · 5 = 5×10⁴ W = 50 kW.'),
  ('Boyu 1 m olan çeyrek dalga (λ/4) bir monopol anten, yaklaşık hangi frekansta verimli çalışır? (c = 3 × 10⁸ m/s)', '75 MHz', ['300 MHz', '3 MHz', '750 MHz'], 'λ/4 = 1 m ise λ = 4 m; f = c/λ = 3×10⁸/4 = 7,5 × 10⁷ Hz = 75 MHz.'),
  ('Işık şiddeti 1000 W/m² olan bir Güneş ışınımı, tam soğurucu bir yüzeye dik düştüğünde uyguladığı ışınım basıncı yaklaşık kaç paskaldır? (P = I/c, c = 3 × 10⁸ m/s)', '3,3 × 10⁻⁶ Pa', ['3,3 × 10⁻³ Pa', '3 × 10¹¹ Pa', '6,7 × 10⁻⁶ Pa'], 'Tam soğurucuda P = I/c = 1000/(3×10⁸) ≈ 3,3×10⁻⁶ Pa; tam yansıtıcıda bu değer iki katı olurdu.'),
  ('MR cihazında 1,5 T\'lık alanda hidrojen çekirdeğinin (proton) rezonans frekansı yaklaşık kaç MHz\'dir? (Protonun γ/2π ≈ 42,58 MHz/T)', '64 MHz', ['28 MHz', '42,6 MHz', '1,5 MHz'], 'f = (γ/2π) B = 42,58 · 1,5 ≈ 63,9 MHz; radyo dalgası bandındadır.'),
  ('Yüksek enerjili parçacık için p ≈ 0,3·B·r bağıntısı (p: GeV/c, B: T, r: m) geçerlidir. 7 TeV\'lik protonları 8,3 T\'lık alanda dairesel yörüngede tutmak için gereken yarıçap yaklaşık kaç kilometredir?', '2,8 km', ['28 km', '0,28 km', '8,3 km'], 'p = 7000 GeV/c; r = p/(0,3B) = 7000/(0,3·8,3) ≈ 2800 m ≈ 2,8 km.'),
  ('Bir proton 0,5 T\'lık düzgün alana dik olarak girip yarım çember çizdikten sonra alandan çıkıyor. Alanda geçirdiği süre yaklaşık kaçtır? (m = 1,67 × 10⁻²⁷ kg, q = 1,6 × 10⁻¹⁹ C)', '66 ns', ['6,6 ns', '131 ns', '660 ns'], 'Yarım tur süresi t = T/2 = πm/(qB) = π · 1,67×10⁻²⁷ / (1,6×10⁻¹⁹ · 0,5) ≈ 6,6×10⁻⁸ s = 66 ns.'),
  ('Yarıçapı r olan çembersel yörüngeyle hareket eden bir parçacık, alan bölgesine dik girip genişliği r/2 olan bölgeden geçerek çıkıyor. İlk doğrultusundan ne kadar sapar?', '30°', ['45°', '60°', '15°'], 'Bölge genişliği d için sinθ = d/r = 1/2 olduğundan sapma açısı 30°\'dir.'),
  ('Hız seçicinin E = 1 × 10⁵ V/m ve B₁ = 0,1 T alanlarından sapmadan geçen, kütlesi 3,2 × 10⁻²⁶ kg ve yükü 1,6 × 10⁻¹⁹ C olan iyonlar, ardından B₂ = 0,5 T\'lık alana dik girerek çembersel yörüngeye giriyor. Yörünge yarıçapı kaç santimetredir?', '40 cm', ['10,5 cm', '80 cm', '20 cm'], 'v = E/B₁ = 10⁶ m/s; r = mv/(qB₂) = 3,2×10⁻²⁶ · 10⁶ / (1,6×10⁻¹⁹ · 0,5) = 0,4 m = 40 cm.'),
  ('1 T\'lık alanda dairesel yörüngede dolanan bir protonun eşdeğer akımı (I = e/T) yaklaşık kaçtır? (T = 2πm/(eB), m = 1,67 × 10⁻²⁷ kg, e = 1,6 × 10⁻¹⁹ C)', '2,4 × 10⁻¹² A', ['1,6 × 10⁻¹⁹ A', '6,6 × 10⁻⁸ A', '3,8 × 10⁻¹¹ A'], 'T = 2π · 1,67×10⁻²⁷ / (1,6×10⁻¹⁹) ≈ 6,6×10⁻⁸ s; I = e/T ≈ 2,4 × 10⁻¹² A.'),
  ('Birbirine dik E = 100 V/m ve B = 0,05 T alanlarında hareket eden yüklü parçacıkların ortalama sürüklenme hızı kaç m/s\'dir?', '2000 m/s', ['5 m/s', '0,0005 m/s', '20 000 m/s'], 'Çapraz alanlarda parçacıklar ortalama E/B hızıyla, yükün işaretinden ve kütlesinden bağımsız olarak sürüklenir: 100 / 0,05 = 2000 m/s.'),
  ('Güneş rüzgârından gelen bir proton, Dünya\'nın yaklaşık 50 μT\'lık alanında dolanıyor. Dolanım (siklotron) frekansı yaklaşık kaç hertzdir? (q = 1,6 × 10⁻¹⁹ C, m = 1,67 × 10⁻²⁷ kg)', '760 Hz', ['76 kHz', '7,6 Hz', '3,8 MHz'], 'f = qB/(2πm) = 1,6×10⁻¹⁹ · 5×10⁻⁵ / (2π · 1,67×10⁻²⁷) ≈ 7,6×10² Hz.'),
  ('Kinetik enerjisi 100 eV olan bir elektron, 0,1 mT\'lık düzgün alana dik girerek çembersel hareket yapıyor. Yörünge yarıçapı yaklaşık kaç metredir? (m = 9,11 × 10⁻³¹ kg, e = 1,6 × 10⁻¹⁹ C)', '0,34 m', ['3,4 m', '0,034 m', '1,2 m'], 'v = √(2K/m) ≈ 5,9×10⁶ m/s; r = mv/(eB) = 9,11×10⁻³¹ · 5,9×10⁶ / (1,6×10⁻¹⁹ · 10⁻⁴) ≈ 0,34 m.'),
  ('Bir laboratuvarda güneye doğru fırlatılan elektron demeti, düşey olarak aşağıya yönelmiş düzgün bir manyetik alandan geçiyor. Demete etkiyen manyetik kuvvet hangi yöndedir?', 'Batıya', ['Doğuya', 'Kuzeye', 'Yukarı'], 'Doğu x, kuzey y, yukarı z alınırsa (−ŷ) × (−ẑ) = x̂ (doğu); elektron negatif olduğundan kuvvet batıya doğrudur.'),
  ('Doğu-batı doğrultusunda gerilmiş bir hat batıya doğru akım taşıyor. Dünya\'nın alanının yatay bileşeni kuzeye bakıyorsa bu bileşenin hatta uyguladığı kuvvet hangi yöndedir?', 'Aşağı doğru', ['Yukarı doğru', 'Doğuya', 'Kuzeye'], 'Doğu x, kuzey y, yukarı z alınırsa I = −x̂, B = ŷ için F ∝ (−x̂) × ŷ = −ẑ; kuvvet aşağı doğrudur.'),
  ('Koordinatlar: x sağa, y yukarı, z okura doğru. +z yönünde ilerleyen bir alfa parçacığı, −x yönündeki alana giriyor. Alfa parçacığına etkiyen kuvvet hangi yöndedir?', '−y yönünde (aşağı)', ['+y yönünde (yukarı)', '−z yönünde (sayfa içine)', '+x yönünde (sağa)'], 'ẑ × (−x̂) = −ŷ; alfa parçacığı pozitif olduğundan kuvvet aşağı yönlüdür.'),
  ('Yarıçapı 3 cm olan bir halkanın merkezindeki alan B₀\'dır. Eksen üzerinde merkezden 4 cm uzaklıktaki noktada alan B₀\'ın kaçta kaçıdır? (B(x) = B₀·R³/(R² + x²)^{3/2})', '0,216 B₀', ['0,5 B₀', '0,36 B₀', '0,125 B₀'], 'R³/(R²+x²)^{3/2} = 27/125 = 0,216 olduğundan alan B₀\'ın 0,216 katıdır.'),
  ('10 cm yarıçaplı bir halkadan 5 A akım geçiyor. Aynı düzlemde, halkaya teğet geçen uzun düz telden de 5 A akım geçmektedir (halkanın merkezi ile tel arası 10 cm). Her iki akımın merkezde oluşturduğu alanlar aynı yönlü ise bileşke alan yaklaşık kaç teslada? (μ₀ = 4π × 10⁻⁷ T·m/A, π = 3,14)', '4,1 × 10⁻⁵ T', ['2,15 × 10⁻⁵ T', '3,1 × 10⁻⁵ T', '1,0 × 10⁻⁵ T'], 'Halka: μ₀I/(2R) ≈ 3,14×10⁻⁵ T; tel: μ₀I/(2πR) = 1×10⁻⁵ T. Aynı yönlü olduklarından toplam ≈ 4,14×10⁻⁵ T.'),
  ('2 μC yük taşıyan, yarıçapı 10 cm olan ince bir yalıtkan halka, kendi düzlemine dik eksen etrafında saniyede 50 devir yapıyor. Halkanın merkezindeki manyetik alan yaklaşık kaç teslada? (μ₀ = 4π × 10⁻⁷ T·m/A)', '6,3 × 10⁻¹⁰ T', ['6,3 × 10⁻⁷ T', '1,3 × 10⁻⁹ T', '3,1 × 10⁻¹⁰ T'], 'Dönen yük akımı I = q·f = 2×10⁻⁶ · 50 = 10⁻⁴ A; B = μ₀I/(2R) = 4π×10⁻⁷ · 10⁻⁴ / 0,2 ≈ 6,3×10⁻¹⁰ T.'),
  ('Biot-Savart yasasına göre, 10 A akım taşıyan telin 1 mm\'lik küçük bir parçasının, parçaya dik doğrultuda 5 cm uzaktaki bir noktada oluşturduğu alan kaç teslada? (dB = μ₀I·dl·sinθ/(4πr²), μ₀/4π = 10⁻⁷ T·m/A)', '4 × 10⁻⁷ T', ['4,5 × 10⁻⁵ T', '2 × 10⁻⁷ T', '4 × 10⁻⁹ T'], 'dB = 10⁻⁷ · 10 · 10⁻³ · 1 / (0,05)² = 10⁻⁹ / 2,5×10⁻³ = 4 × 10⁻⁷ T.'),
  ('Kutup alanı 20 cm² ve yüzeyindeki alan 1 T olan bir elektromıknatısın çekim kuvveti yaklaşık kaç newtondur? (F = B²A/(2μ₀), μ₀ = 4π × 10⁻⁷ T·m/A)', '800 N', ['80 N', '8000 N', '400 N'], 'F = 1² · 2×10⁻³ / (2 · 4π×10⁻⁷) ≈ 796 N ≈ 800 N.'),
  ('İndüktansı 0,1 H olan bir bobinden i = 4 sin(100t) (amper, t saniye) akımı geçiyor. Bobinin uçlarında oluşan emk\'nın en büyük değeri kaç volttur?', '40 V', ['0,4 V', '4 V', '400 V'], 'ε = L·di/dt = 0,1 · 400 cos(100t); en büyük değer 0,1 · 100 · 4 = 40 V.'),
  ('50 sarımlı, alanı 0,01 m² olan bir bobin, düzlemine dik duran ve B = 0,2 sin(100πt) (T) bağıntısıyla değişen bir alanda bulunuyor. Bobinde indüklenen emk\'nın en büyük değeri yaklaşık kaç volttur?', '31,4 V', ['10 V', '3,14 V', '100 V'], 'ε = N A dB/dt; en büyük değer N·A·B₀·ω = 50 · 0,01 · 0,2 · 100π ≈ 31,4 V.'),
  ('100 sarımlı, alanı 0,02 m² olan dikdörtgen bir bobin, 0,5 T\'lık alanda dakikada 600 devirle sabit hızla dönüyor. Üretilen emk\'nın etkin değeri yaklaşık kaç volttur?', '44 V', ['63,5 V', '31 V', '88 V'], 'f = 10 Hz, ω = 62,8 rad/s; ε₀ = NBAω = 100·0,5·0,02·62,8 ≈ 62,8 V; etkin değer ε₀/√2 ≈ 44 V.'),
  ('Alternatörün sargıları 2 kutup çiftli (4 kutuplu) yapılmıştır. 50 Hz frekansta alternatif akım üretmek için rotor dakikada kaç devir yapmalıdır?', '1500', ['3000', '750', '50'], 'f = p·n/60 formülünde p = 2 ve f = 50 Hz için n = 50·60/2 = 1500 devir/dakikadır.'),
  ('12 kutup çiftli bir hidroelektrik santral alternatörü 50 Hz üretiyor. Rotorun dönüş hızı dakikada kaç devirdir?', '250', ['600', '3000', '50'], 'n = 60f/p = 60·50/12 = 250 devir/dakika.'),
  ('Direnci 3 Ω olan bir halkada 0,06 V\'luk sabit emk 0,3 saniye boyunca indüklenirse bu sürede halkada açığa çıkan ısı kaç joule olur?', '3,6 × 10⁻⁴ J', ['6 × 10⁻³ J', '1,2 × 10⁻³ J', '3,6 × 10⁻² J'], 'Isı Q = (ε²/R)·Δt = (0,06²/3) · 0,3 = 3,6 × 10⁻⁴ J.'),
  ('Alanın 0,2 T/s hızla düzgün arttığı, 10 cm yarıçaplı silindirik bir bölgede alan çizgilerini çevreleyen çember üzerinde, bölge kenarında indüklenen elektrik alanın büyüklüğü kaç V/m\'dir? (E·2πr = π r²·dB/dt)', '0,01 V/m', ['0,2 V/m', '0,002 V/m', '0,1 V/m'], 'E = (r/2)·dB/dt = 0,05 · 0,2 = 0,01 V/m.'),
  ('Sarım oranı N₁/N₂ = 5 olan ideal bir transformatörün ikincilinde 4 Ω\'luk bir yük bulunuyor. Birincil devreden bakıldığında bu yük kaç ohm gibi görünür? (R₁ = (N₁/N₂)²·R₂)', '100 Ω', ['20 Ω', '0,16 Ω', '0,8 Ω'], 'R₁ = (N₁/N₂)² R₂ = 25 · 4 = 100 Ω; bu ilke empedans uydurmada kullanılır.'),
  ('Eğim açısı 30° olan sürtünmesiz iletken raylar üzerinde kayan 0,1 kg\'lık çubuğun boyu 0,5 m\'dir. Raylar arası devre direnci 2,5 Ω\'dur ve eğik düzleme dik 1 T\'lık alan vardır. Çubuğun ulaşacağı sınır hız kaç m/s\'dir? (g = 10 m/s²)', '5 m/s', ['2,5 m/s', '10 m/s', '1,25 m/s'], 'Sınır hızda mg sinθ = B²L²v/R; v = 0,1·10·0,5·2,5/(1·0,25) = 5 m/s.'),
  ('0,02 kg kütleli ve 0,4 m uzunluğundaki yatay bir çubuk, iki ince iletken telle asılmıştır. Çubuğa dik, yatay 0,1 T\'lık alan uygulanıp 5 A akım verilirse ipler düşeyle kaç derece sapar? (g = 10 m/s²)', '45°', ['30°', '60°', '37°'], 'tanθ = BIL/mg = 0,1·5·0,4 / (0,02·10) = 0,2/0,2 = 1 → θ = 45°.'),
  ('Kütlesi 0,1 kg ve boyu 0,4 m olan iletken bir çubuk, 45° eğimli sürtünmesiz bir düzlem üzerinde duruyor. Ortamda düşey doğrultulu 0,5 T\'lık düzgün bir manyetik alan vardır. Çubuğun kaymadan dengede kalması için çubuktan kaç amper akım geçmelidir? (g = 10 m/s²)', '5 A', ['2,5 A', '10 A', '1 A'], 'Yatay manyetik kuvvet F = BIL, ağırlığın eğik düzlem boyunca bileşenini dengelemeli: BIL cos45° = mg sin45° → BIL = mg → I = 1/(0,5·0,4) = 5 A.'),
  ('AM radyo bandının tamamını (540–1600 kHz) taramak için kullanılan LC ayar devresinde kondansatörün en büyük kapasitesinin en küçüğüne oranı yaklaşık kaç olmalıdır?', '8,8', ['3,0', '1,7', '26'], 'f ∝ 1/√C olduğundan C ∝ 1/f²; oran (1600/540)² ≈ 8,8\'dir.'),
  ('Çevresi 40 cm olan kare ve dairesel iki halka, aynı değişen alana dik yerleştiriliyor. İndüklenen emk\'lar oranı ε(daire)/ε(kare) yaklaşık kaçtır?', '1,27', ['0,79', '1,57', '2'], 'Kare alanı 100 cm²; daire r = 40/2π ≈ 6,37 cm → A ≈ 127 cm². Oran A_daire/A_kare = 4/π ≈ 1,27.'),
  ('10 A akım taşıyan uzun düz bir telin yanında, aynı düzlemde 5 A akım taşıyan 20 cm boyunda dikdörtgen bir çerçeve bulunuyor. Çerçevenin telle paralel iki kenarı telden 5 cm ve 15 cm uzaklıktadır ve yakın kenardaki akım telle aynı yönlüdür. Çerçeveye etkiyen net kuvvetin büyüklüğü yaklaşık kaç newtondur? (μ₀/2π = 2 × 10⁻⁷ T·m/A)', '2,7 × 10⁻⁵ N', ['8 × 10⁻⁵ N', '5,3 × 10⁻⁵ N', '1,3 × 10⁻⁵ N'], 'Yakın kenar çekilir: 2×10⁻⁷·10·5·0,2/0,05 = 4×10⁻⁵ N; uzak kenar itilir: 1,33×10⁻⁵ N. Net kuvvet ≈ 2,7×10⁻⁵ N olup tele doğrudur.'),
  ('Manyetik momenti 0,5 A·m² olan bir akım halkası, 0,2 T\'lık düzgün alanda kararlı denge konumundan (μ ∥ B) 180° çevrilerek kararsız konuma getiriliyor. Dış etkenin yapması gereken iş kaç joule\'dür? (U = −μB cosθ)', '0,2 J', ['0,15 J', '0,4 J', '0'], 'İş, potansiyel enerji farkına eşittir: U(180°) − U(0°) = μB − (−μB) = 2μB = 2 · 0,5 · 0,2 = 0,2 J.'),
  ('Kalınlığı 0,1 mm olan yarıiletken bir şeritten 1 A akım geçerken şerit yüzeyine dik 1 T\'lık alanda Hall gerilimi 62,5 μV ölçülüyor. Yük taşıyıcı yoğunluğu kaç m⁻³\'tür? (n = BI/(q·t·V_H), q = 1,6 × 10⁻¹⁹ C)', '1 × 10²⁷ m⁻³', ['1 × 10²⁸ m⁻³', '8,5 × 10²⁸ m⁻³', '1 × 10²⁰ m⁻³'], 'n = 1·1 / (1,6×10⁻¹⁹ · 10⁻⁴ · 6,25×10⁻⁵) = 1 × 10²⁷ m⁻³.'),
  ('Direnci 5 Ω, indüktansı 0,5 H olan bir bobin sabit bir gerilim kaynağına bağlanıyor. Akımın kararlı değerinin yarısına ulaşması için gereken süre yaklaşık kaç milisaniyedir? (ln2 ≈ 0,693)', '69 ms', ['100 ms', '50 ms', '139 ms'], 'τ = L/R = 0,1 s; I = I₀/2 için 1 − e^(−t/τ) = 1/2 → t = τ ln2 ≈ 0,0693 s ≈ 69 ms.'),
  ('2 μF\'lık bir kondansatör 100 V\'a yüklenip direnci ihmal edilebilir 0,5 H\'lik bir bobine boşaltılıyor. Bobinden geçen en büyük akım kaç amperdir?', '0,2 A', ['0,02 A', '2 A', '0,1 A'], '½CV² = ½LI² → I = V√(C/L) = 100 · √(2×10⁻⁶ / 0,5) = 100 · 2×10⁻³ = 0,2 A.'),
  ('İndüktansı 0,1 H olan bir bobinde 2 A akım varken akımın bütün enerjisi 10 μF\'lık bir kondansatöre aktarılırsa kondansatörün en büyük gerilimi kaç volt olur?', '200 V', ['20 V', '2000 V', '100 V'], '½LI² = ½CV² → V = I√(L/C) = 2 · √(0,1/10⁻⁵) = 2 · 100 = 200 V.'),
  ('Hat gerilimi 380 V olan dengeli bir üç fazlı sistemde bir motor 10 A akım çekiyor ve güç katsayısı 0,8\'dir. Motorun gerçek gücü yaklaşık kaç kilowatt\'tır? (P = √3·V·I·cosφ)', '5,3 kW', ['3,05 kW', '9,1 kW', '3,8 kW'], 'P = 1,73 · 380 · 10 · 0,8 ≈ 5265 W ≈ 5,3 kW.'),
  ('Ses bobini 40 sarımlı, yarıçapı 1,5 cm olan bir hoparlörde bobin, 1 T\'lık radyal alan içindedir ve 0,5 A akım taşıyor. Bobine etkiyen kuvvet yaklaşık kaç newtondur?', '1,9 N', ['0,05 N', '0,47 N', '7,5 N'], 'Tel uzunluğu L = N·2πr = 40 · 2π · 0,015 ≈ 3,77 m; F = BIL = 1 · 0,5 · 3,77 ≈ 1,9 N.'),
  ('Tanjant galvanometresinde 10 sarımlı, yarıçapı 5 cm olan bobinin merkezindeki küçük pusula, Dünya\'nın alanının yatay bileşeni 2 × 10⁻⁵ T iken 45° sapıyor. Bobinden geçen akım yaklaşık kaç amperdir? (μ₀ = 4π × 10⁻⁷ T·m/A)', '0,16 A', ['0,016 A', '1,6 A', '0,32 A'], 'tan45° = 1 → B_bobin = B_Dünya; μ₀NI/(2R) = 2×10⁻⁵ → I = 2·0,05·2×10⁻⁵ / (4π×10⁻⁷ · 10) ≈ 0,16 A.'),
  ('Yarıçapı 10 cm olan, her biri 100 sarımlı iki özdeş bobin Helmholtz düzeninde (aralarındaki uzaklık yarıçapa eşit) kuruluyor ve 1 A akım taşıyor. Aralarındaki orta noktada alan yaklaşık kaç militesladır? (B = (4/5)^{3/2}·μ₀NI/R)', '0,90 mT', ['0,45 mT', '1,8 mT', '0,13 mT'], 'B = 0,716 · 4π×10⁻⁷ · 100 · 1 / 0,1 ≈ 9,0×10⁻⁴ T = 0,90 mT.'),
  ('Sürtünmesiz yatay raylar üzerindeki 0,2 kg kütleli ve 0,5 m uzunluklu bir çubuğa 5 m/s ilk hız verilip bırakılıyor. Raylar arası devrenin toplam direnci 2 Ω ve düşey alan 1 T ise çubuk durana kadar kaç metre yol alır?', '8 m', ['2,5 m', '4 m', '20 m'], 'Hız azalırken F = −B²L²v/R etkir; durana kadarki yol x = m v₀ R/(B²L²) = 0,2·5·2/(1·0,25) = 8 m.'),
  ('Bir protonu 1000 V\'luk gerilimle durgun hâlden hızlandırıp 0,1 T\'lık düzgün alana dik gönderiyoruz. Yörünge yarıçapı yaklaşık kaç santimetredir? (m = 1,67 × 10⁻²⁷ kg, q = 1,6 × 10⁻¹⁹ C)', '4,6 cm', ['14,5 cm', '1,5 cm', '46 cm'], 'v = √(2qV/m) ≈ 4,4×10⁵ m/s; r = mv/(qB) = √(2mV/q)/B ≈ 4,6×10⁻² m.'),
  ('Boşlukta B = 0,2 T\'lık düzgün bir manyetik alanın bulunduğu 0,01 m³\'lük hacimde depolanan manyetik enerji yaklaşık kaç joule\'dür? (u = B²/(2μ₀), μ₀ = 4π × 10⁻⁷ T·m/A)', '159 J', ['16 J', '1590 J', '2,5 J'], 'W = B²V/(2μ₀) = 0,04 · 0,01 / (2 · 4π×10⁻⁷) ≈ 159 J.'),
  ('İndüktansları 0,4 H ve 0,1 H olan iki bobin arasındaki bağlaşım katsayısı k = 0,5\'tir. Karşılıklı indüktans kaç henry\'dir? (M = k√(L₁L₂))', '0,1 H', ['0,2 H', '0,05 H', '0,5 H'], 'M = 0,5 · √(0,4 · 0,1) = 0,5 · 0,2 = 0,1 H.'),
  ('Karşılıklı indüktansı 0,1 H olan iki bobin, akımları aynı yönde dolaşacak biçimde seri bağlanıyor. Bobinlerin öz indüktansları 0,4 H ve 0,1 H ise toplam indüktans kaç henry\'dir? (L = L₁ + L₂ + 2M)', '0,7 H', ['0,55 H', '0,6 H', '0,9 H'], 'L = 0,4 + 0,1 + 2 · 0,1 = 0,7 H.'),
  ('Yarıçapları 10 cm olan, düzlemleri birbirine dik ve ortak merkezli iki halkadan 5 A\'er akım geçiyor. Ortak merkezdeki alan yaklaşık kaç teslada? (μ₀ = 4π × 10⁻⁷ T·m/A, π = 3,14)', '4,4 × 10⁻⁵ T', ['3,15 × 10⁻⁵ T', '6,3 × 10⁻⁵ T', '2,2 × 10⁻⁵ T'], 'Her halka merkezde μ₀I/(2R) = 3,14×10⁻⁵ T verir; alanlar birbirine dik olduğundan bileşke √2 · 3,14×10⁻⁵ ≈ 4,4×10⁻⁵ T\'dır.'),
  ('Kenarı 20 cm olan kare bir tel çerçeveden 5 A akım geçiyor. Karenin merkezindeki alan yaklaşık kaç teslada? (B = 2√2·μ₀I/(πa), μ₀ = 4π × 10⁻⁷ T·m/A)', '2,8 × 10⁻⁵ T', ['1,45 × 10⁻⁵ T', '5,7 × 10⁻⁵ T', '1,0 × 10⁻⁵ T'], 'B = 2√2 · 4π×10⁻⁷ · 5 / (π · 0,2) = 2√2 · 10⁻⁵ ≈ 2,8×10⁻⁵ T.'),
  ('Bir hızlandırıcıda 100 GeV/c momentumlu bir parçacığı 5 T\'lık alanda çembersel yörüngede tutmak için gereken yarıçap yaklaşık kaç metredir? (p = 0,3·B·r; p: GeV/c, B: T, r: m)', '67 m', ['6,7 m', '670 m', '15 m'], 'r = p/(0,3B) = 100/(0,3·5) ≈ 66,7 m.'),
  ('e/m deneyinde 150 V\'la hızlandırılan elektronlar, 0,8 mT\'lık düzgün alanda yarıçapı 5,0 cm olan çember çiziyor. Yük/kütle oranı yaklaşık kaç C/kg bulunur? (e/m = 2V/(B·r)²)', '1,9 × 10¹¹', ['3,8 × 10¹¹', '9,4 × 10¹⁰', '1,9 × 10⁷'], 'e/m = 2·150 / (0,8×10⁻³ · 0,05)² = 300 / 1,6×10⁻⁹ ≈ 1,9 × 10¹¹ C/kg.'),
  ('Uzun düz bir telden yukarı doğru akım geçiyor ve akım artıyor. Telin sağında, aynı düzlemde duran dikdörtgen bir iletken çerçevedeki indüksiyon akımı hangi yöndedir?', 'Saat yönünün tersine', ['Saat yönünde', 'Akım oluşmaz', 'Önce saat yönünde, sonra tersine'], 'Telin sağında alan sayfaya içe doğrudur ve artmaktadır; çerçeve dışa doğru alan oluşturmak için saat yönünün tersine akım dolaştırır.'),
  ('Seri RLC devresinde dirençte 30 V, bobinde 90 V ve kondansatörde 50 V etkin gerilim ölçülüyor. Kaynak gerilimi kaç volttur?', '50 V', ['170 V', '110 V', '90 V'], 'V = √(VR² + (VL − VC)²) = √(900 + 1600) = 50 V.'),
  ('Alternatif gerilim kaynağına paralel bağlanmış bir direnç ve bir saf bobinden sırasıyla 6 A ve 8 A etkin akım geçiyor. Kaynaktan çekilen toplam etkin akım kaç amperdir?', '10 A', ['14 A', '2,5 A', '7 A'], 'Direnç ve bobin akımları 90° faz farklı olduğundan I = √(6² + 8²) = 10 A olur.'),
  ('Etkin gerilimi 220 V, frekansı 50 Hz olan şebekeden 1000 W çeken ve güç katsayısı 0,6 olan bir yükün güç katsayısını 1\'e çıkarmak için paralel kondansatör bağlanacaktır. Kondansatörün kapasitesi yaklaşık kaç mikrofarad olmalıdır?', '88 μF', ['8,8 μF', '880 μF', '52 μF'], 'Reaktif güç Q = P·tanφ = 1000 · 1,333 = 1333 var; C = Q/(ωV²) = 1333/(314 · 220²) ≈ 8,8×10⁻⁵ F ≈ 88 μF.'),
  ('Bir yarım dalga doğrultucunun çıkışında akım, sinüsün yalnız pozitif yarım periyotlarından oluşuyor ve tepe değeri 10 A. Akımın etkin değeri kaç amperdir?', '5 A', ['7,07 A', '3,18 A', '10 A'], 'Yarım dalgada Irms = Imax/2 = 5 A; tam dalga sinüste ise Imax/√2 ≈ 7,07 A olurdu.'),
  ('v = 5 + 5 sin(ωt) (volt) gerilimin etkin değeri yaklaşık kaç volttur?', '6,1 V', ['7,1 V', '5 V', '10 V'], 'V_rms² = 5² + 5²/2 = 37,5 → V_rms ≈ 6,1 V.'),
  ('N = 1000 sarımlı, kesit alanı 4 cm² ve ortalama yarıçapı 10 cm olan bir toroidin (boş) indüktansı kaç milihenrydir? (L = μ₀N²A/(2πr))', '0,8 mH', ['8 mH', '0,08 mH', '80 mH'], 'L = 4π×10⁻⁷ · 10⁶ · 4×10⁻⁴ / (2π · 0,1) = 8×10⁻⁴ H = 0,8 mH.'),
  ('Kaynak gerilimi 12 V, direnci 4 Ω ve indüktansı 2 H olan bir RL devresinde anahtar kapatıldıktan bir zaman sabiti sonra akım yaklaşık kaç amper olur?', '1,9 A', ['3 A', '1,1 A', '2,4 A'], 'Son akım 12/4 = 3 A; τ = 0,5 s\'de I = 3(1 − e⁻¹) ≈ 1,9 A.'),
  ('Etkin (rms) elektrik alanı 100 V/m olan düzlem bir elektromanyetik dalganın boşluktaki şiddeti yaklaşık kaç W/m²\'dir? (I = ε₀·c·E_rms², ε₀ = 8,85 × 10⁻¹² C²/(N·m²), c = 3 × 10⁸ m/s)', '27 W/m²', ['13 W/m²', '2,7 W/m²', '270 W/m²'], 'Etkin alan için I = ε₀ c E_rms² = 8,85×10⁻¹² · 3×10⁸ · 10⁴ ≈ 26,6 W/m².'),
  ('Elektrik alan şiddeti E ile manyetik alan şiddeti B arasında E = cB eşdeğerliği (enerji yoğunluğu bakımından) kullanılırsa 1 T\'lık manyetik alana eşdeğer elektrik alan yaklaşık kaç V/m\'dir? (c = 3 × 10⁸ m/s)', '3 × 10⁸ V/m', ['3 × 10⁻⁸ V/m', '9 × 10¹⁶ V/m', '1 × 10⁶ V/m'], 'Boşluktaki elektromanyetik dalgada enerji yoğunlukları eşit olduğunda E = cB = 3×10⁸ · 1 = 3×10⁸ V/m olur.'),
  ('Süperiletken manyetik enerji depolama (SMES) sistemlerinde 1 H\'lik bir bobinden 10 kA akım geçiyorsa depolanan enerji kaç megajoule\'dür?', '50 MJ', ['100 MJ', '5 MJ', '500 MJ'], 'W = ½LI² = 0,5 · 1 · (10⁴)² = 5×10⁷ J = 50 MJ.'),
  ('Düzlemine dik 0,2 T\'lık düzgün alana yerleştirilmiş, yarıçapı 5 cm olan esnek dairesel bir halkadan 10 A akım geçiyor. Halka telinin her bir kesitindeki gerilme kuvveti (T = B·I·R) kaç newtondur?', '0,1 N', ['0,01 N', '1 N', '0,5 N'], 'Dairesel esnek halkada gerilme T = BIR = 0,2 · 10 · 0,05 = 0,1 N\'dir.'),
  ('Bir proton, sağa doğru 2 × 10⁶ m/s hızla ilerlerken yukarı yönlü 10⁴ V/m\'lik elektrik alan ve manyetik kuvvetin aşağı yönde olacağı biçimde yönelmiş 0,01 T\'lık manyetik alan bulunan bölgeye giriyor. Protona etkiyen net kuvvetin büyüklüğü kaç newtondur? (q = 1,6 × 10⁻¹⁹ C)', '1,6 × 10⁻¹⁵ N', ['4,85 × 10⁻¹⁵ N', '3,2 × 10⁻¹⁵ N', '0'], 'Elektrik kuvvet qE = 1,6×10⁻¹⁵ N yukarı; manyetik kuvvet qvB = 3,2×10⁻¹⁵ N aşağı. Net kuvvet 1,6×10⁻¹⁵ N\'dir ve aşağı yönlüdür.'),
  ('L indüktansı ve C kapasitesi olan bir LC devresi için √(LC) ifadesinin SI birimi nedir?', 'Saniye', ['Hertz', 'Ohm', 'Volt'], 'LC çarpımı s² birimindedir (L = Ω·s, C = s/Ω); karekökü saniyedir ve rezonans periyoduyla ilişkilidir.'),
  ('Yarıçapı 2 mm olan uzun, düz bir telden kesite düzgün dağılmış 20 A akım geçiyor. Eksenden 1 mm uzaklıkta (tel içinde) alan kaç militesladır? (B = μ₀Ir/(2πR²), μ₀/2π = 2 × 10⁻⁷ T·m/A)', '1 mT', ['2 mT', '0,5 mT', '4 mT'], 'B = 2×10⁻⁷ · 20 · 10⁻³ / (2×10⁻³)² = 4×10⁻⁹ / 4×10⁻⁶ = 10⁻³ T = 1 mT.'),
  ('Kapalı bir çevrenin içinden 5 A akım sayfaya içe, 3 A akım sayfadan dışa doğru geçiyor. Ampère yasasına göre bu çevre boyunca ∮B·dl kaç T·m\'dir? (μ₀ = 4π × 10⁻⁷ T·m/A)', '2,5 × 10⁻⁶ T·m', ['1,0 × 10⁻⁵ T·m', '5 × 10⁻⁷ T·m', '6,3 × 10⁻⁶ T·m'], 'Net akım 5 − 3 = 2 A olduğundan ∮B·dl = μ₀ I_net = 4π×10⁻⁷ · 2 ≈ 2,5×10⁻⁶ T·m.'),
  ('Etkin gerilimi 220 V ve frekansı 50 Hz olan şebekeye bağlı, birincil sargısı 500 sarımlı ideal bir transformatörde çekirdeğin en büyük manyetik akısı yaklaşık kaç miliweberdir? (V_max = N·ω·Φ_max)', '2 mWb', ['0,2 mWb', '20 mWb', '14 mWb'], 'V_max = 311 V; Φ_max = V_max/(Nω) = 311 / (500 · 314) ≈ 2×10⁻³ Wb = 2 mWb.'),
  ('Kapasitesi 2 μF olan bir kondansatörün uçlarındaki gerilim 5 × 10⁵ V/s hızla artıyor. Plakalar arasındaki yer değiştirme akımı kaç amperdir? (I_d = C·dV/dt)', '1 A', ['10 A', '0,1 A', '2,5 A'], 'Plakalar arasındaki yer değiştirme akımı, devredeki iletim akımına eşittir: I = C·dV/dt = 2×10⁻⁶ · 5×10⁵ = 1 A.'),
  ('Bir elektromıknatısın hava aralığı iki katına çıkarılır ve sargı akımı sabit tutulursa, çekim kuvveti yaklaşık nasıl değişir? (Aralıkta alan, aralıkla ters orantılı kabul edilsin.)', 'Dörtte birine düşer.', ['Yarıya düşer.', 'İki katına çıkar.', 'Hiçbir değişiklik göstermez.'], 'B ∝ 1/aralık olduğundan kuvvet B² ile 1/4\'e iner.'),
  ('Direnci doğru akımda 10 Ω ölçülen bir bobine 50 Hz alternatif gerilim uygulandığında gerilim/akım oranı 50 Ω bulunuyor. Bobinin indüktif reaktansı yaklaşık kaç ohmdur?', '49 Ω', ['40,5 Ω', '60 Ω', '10 Ω'], 'Z² = R² + XL² → XL = √(50² − 10²) = √2400 ≈ 49 Ω.'),
  ('Bir ferromanyetik çekirdekte H = 1000 A/m ve mıknatıslanma M = 9 × 10⁵ A/m ise çekirdekteki B yaklaşık kaç teslada? (B = μ₀(H + M), μ₀ = 4π × 10⁻⁷ T·m/A)', '1,13 T', ['1,26 × 10⁻³ T', '0,9 T', '11,3 T'], 'B = 4π×10⁻⁷ · (1000 + 900 000) ≈ 1,13 T; yani katkının büyük bölümü mıknatıslanmadan gelir.'),
  ('Hidrojen atomunun taban durumunda, yarıçapı 5,3 × 10⁻¹¹ m olan yörüngede dolanan elektronun eşdeğer akımı yaklaşık 1,05 mA\'dir. Yörünge merkezinde bu akımın oluşturduğu alan yaklaşık kaç teslada? (B = μ₀I/(2r), μ₀ = 4π × 10⁻⁷ T·m/A)', '12,4 T', ['1,24 T', '124 T', '0,12 T'], 'B = 4π×10⁻⁷ · 1,05×10⁻³ / (2 · 5,3×10⁻¹¹) ≈ 12,4 T; atomik ölçekte çok güçlü alanlar oluşabilir.'),
  ('Protonun presesyon (Larmor) frekansı yaklaşık 42,58 MHz/T\'dır. Dünya\'nın 50 μT\'lık alanında protonlar kaç hertz\'lik frekansla presesyon yapar?', '2,1 kHz', ['2,1 MHz', '85 Hz', '42,6 Hz'], 'f = 42,58×10⁶ · 50×10⁻⁶ ≈ 2130 Hz; proton presesyon manyetometreleri bu ilişkiyle alanı çok duyarlı ölçer.'),
  ('Elektron spin rezonansı (ESR) yaklaşık 28 GHz/T oranıyla gerçekleşir. 0,35 T\'lık alanda ESR frekansı yaklaşık kaç GHz\'dir?', '9,8 GHz', ['28 GHz', '0,35 GHz', '98 GHz'], 'f = 28 · 0,35 ≈ 9,8 GHz; bu değer mikrodalga X bandındadır ve yaygın ESR spektrometrelerinin çalışma bölgesidir.'),
  ('Senkron hızı 1500 dev/dk olan bir asenkron motor, rotoru 1440 dev/dk ile dönerken yüzde kaç kayma (slip) yapar? (s = (n_s − n)/n_s)', '%4', ['%2', '%6', '%0,04'], 's = (1500 − 1440)/1500 = 0,04, yani %4\'tür.'),
  ('Birinci bobindeki akım saniyede 2 A değişirken ikinci bobinde 4 V emk indükleniyor. İkinci bobindeki akım saniyede 5 A değiştirilirse birinci bobinde indüklenen emk kaç volt olur?', '10 V', ['4 V', '2 V', '8 V'], 'M = 4/2 = 2 H\'dir ve M₁₂ = M₂₁ olduğundan birinci bobinde ε = M·ΔI/Δt = 2 · 5 = 10 V olur.'),
  ('İndüktansı 2 μH olan dirençsiz bir halkadan geçen dış akı 4 μWb artıyor. Halkada oluşan sabit tutucu akımın büyüklüğü kaç amperdir? (ΔΦ = L·I)', '2 A', ['8 A', '0,5 A', '1 A'], 'Toplam akı sabit kalır: L·I = ΔΦ_dış → I = 4×10⁻⁶ / 2×10⁻⁶ = 2 A.'),
  ('Bir iletim kesintisi (kısa devre) sırasında paralel duran ve 10 cm arayla yerleştirilmiş iki bara iletkeninden 10 kA\'lik akım zıt yönde geçiyor. Her bir metre iletkene etkiyen itme kuvveti yaklaşık kaç newtondur? (μ₀/2π = 2 × 10⁻⁷ T·m/A)', '200 N', ['20 N', '2000 N', '2 N'], 'F/L = 2×10⁻⁷ · (10⁴)² / 0,1 = 200 N/m; kısa devre kuvvetleri baraların sağlam bağlanmasını zorunlu kılar.'),
];
